"""Actual Files editor/core/code-view/cache/scope; Telegram navigation/settings APIs are named doubles."""
from pathlib import Path
import re,shutil

def write_stubs(source,root):
 def put(path,text):
  p=source/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
 for name in ['FilesCodeView','FilesWork','FilesCache','FlexyFileEditorActivity','FlexyFiles']:
  p=Path('app/flexygram/files')/(name+'.java');put(str(p),(root/'TMessagesProj/src/main/java'/p).read_text())
 for p in (root/'TMessagesProj/src/main/java/app/flexygram/files/core').glob('*.java'):put('app/flexygram/files/core/'+p.name,p.read_text())
 texts='\n'.join(p.read_text()for p in source.rglob('*.java'))
 fields={kind:sorted(set(re.findall(r'R\.'+kind+r'\.(\w+)',texts)))for kind in ['string','drawable']}
 put('org/telegram/messenger/R.java','package org.telegram.messenger;public class R {'+''.join('public static class '+kind+' {'+''.join('public static final int '+n+'='+str(i+1)+';'for i,n in enumerate(names))+'}'for kind,names in fields.items())+'}')
 put('org/telegram/messenger/LocaleController.java','package org.telegram.messenger;public class LocaleController {public static String getString(int id){return "test-label-"+id;}}')
 put('org/telegram/messenger/ApplicationLoader.java','package org.telegram.messenger;public class ApplicationLoader {public static android.content.Context applicationContext=org.robolectric.RuntimeEnvironment.getApplication();}')
 put('org/telegram/messenger/AndroidUtilities.java','''package org.telegram.messenger;public class AndroidUtilities {static android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());public static int dp(float n){return (int)Math.ceil(n);}public static void runOnUIThread(Runnable r){handler.post(r);}public static void runOnUIThread(Runnable r,long ms){handler.postDelayed(r,ms);}public static void cancelRunOnUIThread(Runnable r){handler.removeCallbacks(r);}public static String formatFileSize(long n){return Long.toString(n);}}''')
 put('org/telegram/messenger/SharedConfig.java','package org.telegram.messenger;public class SharedConfig {public static boolean directShare;public static String directShareHash;}')
 put('org/telegram/messenger/MessageObject.java','''package org.telegram.messenger;public class MessageObject {public int currentAccount;public static class Message {public boolean noforwards;public String attachPath;}public static class Document {public long size;}public Message messageOwner=new Message();public String name="file.txt";public Document document=new Document();public Document getDocument(){return document;}public boolean isSending(){return false;}public boolean isSendError(){return false;}public boolean isSecret(){return false;}public boolean isSecretMedia(){return false;}public boolean needDrawBluredPreview(){return false;}public String getDocumentName(){return name;}public long getDialogId(){return 1;}}''')
 put('org/telegram/messenger/FileLoader.java','''package org.telegram.messenger;public class FileLoader {public static int calls;public static final int PRIORITY_NORMAL=1;public static FileLoader getInstance(int i){calls++;return new FileLoader();}public java.io.File getPathToMessage(Object message){return null;}public void loadFile(Object doc,Object parent,int p,int t){}}''')
 put('org/telegram/ui/LaunchActivity.java','package org.telegram.ui;public class LaunchActivity extends android.app.Activity {}')
 put('org/telegram/ui/ActionBar/Theme.java','''package org.telegram.ui.ActionBar;public class Theme {public interface ResourcesProvider {}public static final int key_windowBackgroundWhite=1,key_windowBackgroundWhiteBlackText=2,key_windowBackgroundWhiteGrayText2=3,key_windowBackgroundWhiteBlueText=4;public static int getColor(int key,ResourcesProvider p){return key==1?0xfff7f8fa:key==2?0xff11151c:key==4?0xff287bc0:0xff777777;}}''')
 put('org/telegram/ui/ActionBar/ActionBar.java','''package org.telegram.ui.ActionBar;public class ActionBar {public static class ActionBarMenuOnItemClick {public void onItemClick(int id){}}public void setBackButtonImage(int i){}public void setTitle(String s){}public void setAllowOverlayTitle(boolean b){}public void setActionBarMenuOnItemClick(ActionBarMenuOnItemClick c){}public Menu createMenu(){return new Menu();}public static class Menu {public ActionBarMenuItem addItem(int id,int icon){return new ActionBarMenuItem();}}}''')
 put('org/telegram/ui/ActionBar/ActionBarMenuItem.java','package org.telegram.ui.ActionBar;public class ActionBarMenuItem {public void addSubItem(int id,String text){}}')
 put('org/telegram/ui/ActionBar/BaseFragment.java','''package org.telegram.ui.ActionBar;public class BaseFragment {protected android.view.View fragmentView;protected ActionBar actionBar=new ActionBar();private android.app.Activity activity=org.robolectric.Robolectric.buildActivity(android.app.Activity.class).setup().get();public android.app.Activity getParentActivity(){return activity;}public Theme.ResourcesProvider getResourceProvider(){return null;}public android.view.View createView(android.content.Context c){return null;}public void startActivityForResult(android.content.Intent i,int code){}public android.app.Dialog showDialog(android.app.Dialog d){d.show();return d;}public boolean onBackPressed(boolean invoked){return true;}public boolean isSwipeBackEnabled(android.view.MotionEvent e){return true;}public void finishFragment(){}public void onFragmentDestroy(){}public void onActivityResultFragment(int c,int r,android.content.Intent d){}}''')
 put('org/telegram/ui/ActionBar/AlertDialog.java','''package org.telegram.ui.ActionBar;public class AlertDialog extends android.app.Dialog {public AlertDialog(android.content.Context c){super(c);}public static class Builder {android.content.Context c;android.view.View v;public Builder(android.content.Context c,Theme.ResourcesProvider p){this.c=c;}public Builder setTitle(CharSequence s){return this;}public Builder setMessage(CharSequence s){return this;}public Builder setView(android.view.View view){v=view;return this;}public Builder setPositiveButton(CharSequence s,android.content.DialogInterface.OnClickListener l){return this;}public Builder setNegativeButton(CharSequence s,android.content.DialogInterface.OnClickListener l){return this;}public Builder setNeutralButton(CharSequence s,android.content.DialogInterface.OnClickListener l){return this;}public AlertDialog create(){AlertDialog d=new AlertDialog(c);if(v!=null)d.setContentView(v);return d;}}}''')
 put('app/flexygram/files/FlexyFilesSheet.java','package app.flexygram.files;class FlexyFilesSheet extends android.app.Dialog {FlexyFilesSheet(org.telegram.ui.ActionBar.BaseFragment owner,java.io.File f,String n,long d,int a){super(owner.getParentActivity());}}')
